import{_ as t,o as s,c as o,a4 as a}from"./chunks/framework.DyX1TuK3.js";const u=JSON.parse('{"title":"Technical Decisions — stack, collaboration, and pivots","description":"","frontmatter":{},"headers":[],"relativePath":"en/decisions.md","filePath":"en/decisions.md"}'),n={name:"en/decisions.md"};function r(i,e,d,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="technical-decisions-—-stack-collaboration-and-pivots" tabindex="-1">Technical Decisions — stack, collaboration, and pivots <a class="header-anchor" href="#technical-decisions-—-stack-collaboration-and-pivots" aria-label="Permalink to &quot;Technical Decisions — stack, collaboration, and pivots&quot;">​</a></h1><h2 id="constraints-first-—-every-choice-grew-out-of-these" tabindex="-1">Constraints first — every choice grew out of these <a class="header-anchor" href="#constraints-first-—-every-choice-grew-out-of-these" aria-label="Permalink to &quot;Constraints first — every choice grew out of these&quot;">​</a></h2><ul><li><strong>Timeline</strong>: hackathon scale — measured in weeks, not quarters</li><li><strong>Team</strong>: four people — 1 PM, 2 editors, 1 engineer; engineering itself ran as one person + AI</li><li><strong>Hardware</strong>: the demo box is a 2-vCPU, GPU-less small VPS; budget $0</li><li><strong>Content</strong>: a Chinese film library — every model choice starts with &quot;is it good at Chinese?&quot;</li></ul><p>Guiding principle: <strong>simplify the choices — spend the entire complexity budget on &quot;how the service integrates AI&quot;, and pick the most boring, least likely-to-page-you infrastructure for everything else</strong> (boring technology). The point was never stacking tech; it&#39;s how search, tagging and operations workflows change once AI is in the loop.</p><h2 id="initial-stack-—-what-and-why" tabindex="-1">Initial stack — what and why <a class="header-anchor" href="#initial-stack-—-what-and-why" aria-label="Permalink to &quot;Initial stack — what and why&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choice</th><th>Why</th></tr></thead><tbody><tr><td><strong>Python + FastAPI</strong></td><td>Auto-generated API docs (Swagger) — zero-cost interface conversations with PM / editors; one language across the project, same ecosystem as the AI tooling</td></tr><tr><td><strong>NiceGUI</strong> (pure-Python UI)</td><td>The framework absorbs the frontend details — no second tech stack; one person covers full stack</td></tr><tr><td><strong>SQLite</strong></td><td>Simple, right-sized for a small project — zero ops, a single portable file</td></tr><tr><td><strong>Qdrant</strong></td><td>Used it before; active community, easy to find answers when things break</td></tr><tr><td><strong>bge-m3</strong> (embedding)</td><td>Mainstream open-source embedding model, strong in Chinese, runs fully local</td></tr><tr><td><strong>Local LLM (Ollama)</strong> (LLM)</td><td>Originally cloud free tier + auto-fallback on rate limits (designed assuming 429s); but the free tier proved too unstable (429s, models delisted) and calling cloud first only added retry latency — so we pivoted to a local Ollama model with no cloud dependency: self-contained demo, zero quota risk</td></tr><tr><td><strong>Docker Compose + Traefik @ VPS</strong></td><td>Own VPS at zero marginal cost, public URL, no cold starts; four services in one compose file</td></tr></tbody></table><h2 id="how-we-collaborated-—-not-vibe-coding" tabindex="-1">How we collaborated — not vibe coding <a class="header-anchor" href="#how-we-collaborated-—-not-vibe-coding" aria-label="Permalink to &quot;How we collaborated — not vibe coding&quot;">​</a></h2><p>Engineering ran as &quot;one person + AI&quot;, but every step had verifiable discipline: AI produces, the human steers and gates:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Practice</th><th>What it prevents</th></tr></thead><tbody><tr><td><strong>ADRs (decision records)</strong></td><td>every major pivot gets one: context, options, reasons, impact (8 in total)</td><td>amnesia about &quot;why we did it this way&quot;; AI bulldozing old decisions during refactors</td></tr><tr><td><strong>Scored eval loop</strong></td><td>45 real queries auto-scored; every change measured — winners stay, losers roll back (see Eval)</td><td>tuning by vibes; the &quot;it looks better&quot; illusion</td></tr><tr><td><strong>Commit gates</strong></td><td>lint, formatting, secret scanning, tests — even &quot;no hardcoded UI copy&quot; is enforced automatically</td><td>the low-grade mistakes AI sneaks in when producing code at volume</td></tr><tr><td><strong>Git-based deploys</strong></td><td>always commit → push → server pulls → rebuild; no editing files on the box</td><td>drift between demo box and repo; incidents with no rollback or trace</td></tr><tr><td><strong>Human review loop</strong></td><td>AI suggests tags → editors approve/reject each → feedback accumulates into a wiki</td><td>AI&#39;s taste problems sliding through silently</td></tr><tr><td><strong>AI-native workflows</strong></td><td>operational chores (importing films, ingesting awards, library health checks) packaged as natural-language commands (agent skills)</td><td>repetitive ops eating engineering time</td></tr></tbody></table><h2 id="the-mid-project-pivots-adr-digest" tabindex="-1">The mid-project pivots (ADR digest) <a class="header-anchor" href="#the-mid-project-pivots-adr-digest" aria-label="Permalink to &quot;The mid-project pivots (ADR digest)&quot;">​</a></h2><details class="note"><summary>① Pure vector search → Hybrid (BM25 + vectors + RRF + rerank)</summary><p><strong>Pain:</strong> with cosine alone, scores huddled in a narrow 0.55–0.65 band and proper nouns (titles) kept missing.</p><p><strong>Pivot:</strong> following the open-source project qmd — lexical (BM25) and semantic (vector) tracks recall independently, RRF fuses the rankings, a reranker finishes.</p><p><strong>Why:</strong> the two retrievals fail in complementary ways — lexical rescues proper nouns, semantic rescues intent; fusing by rank instead of score sidesteps incomparable score scales.</p></details><details class="note"><summary>② Hand-written keyword parser → LLM query understanding (with a safety net)</summary><p><strong>Pain:</strong> the hand-built keyword table covered 3 dimensions; sentences like &quot;what heals a brutal breakup&quot; had no chance.</p><p><strong>Pivot:</strong> one LLM call expands the query into: 14-dim tag signals + an imagined plot (HyDE) + retrieval keywords.</p><p><strong>Why:</strong> LLMs understand meaning but fail (rate limits / bad output) — so the design falls back to the keyword parser whenever the LLM fails. Search never goes dark because the AI did. Caching makes repeat queries free.</p></details><details class="note"><summary>③ Knobs hardcoded in code → hot-reloaded config + explainable output</summary><p><strong>Pain:</strong> changing one weight meant code changes and rebuilds; search was a black box.</p><p><strong>Pivot:</strong> all weights/thresholds in one JSON, effective on save; every result carries &quot;why it surfaced&quot; (matched conditions + retrieval path).</p><p><strong>Why:</strong> tuning speed = number of experiments; explainability serves debugging and product trust at once.</p></details><details class="note"><summary>④ Hand-set weights → self-correcting eval loop (LLM-as-judge)</summary><p><strong>Pain:</strong> config values were educated guesses; a demo has no real traffic, hence no click data to learn from.</p><p><strong>Pivot:</strong> let an LLM judge score search results, build automated evals — the system measures and tunes itself without traffic.</p><p><strong>Why:</strong> when there&#39;s no signal, manufacture signal. This loop powered the entire v1–v8 tuning story (see Eval).</p></details><details class="note"><summary>⑤ The trench series: stabilizing the local LLM judge (a four-ADR saga)</summary><p>Moving the judge to a local model tripped a chain of pitfalls, one ADR each:</p><ul><li><strong>Cancellation never reached the server</strong> → switch LLM calls to streaming, so client disconnects can stop runaway generation</li><li><strong>Hitting the model mid-warmup</strong> → first a workaround, then dissecting how a mature open-source agent talks to the same service — settled on &quot;SDK + retries absorb the warmup&quot;. Borrowing beats reinventing.</li><li><strong>Responses mysteriously empty</strong> → not a crash: the thinking-style model spent its whole output budget on thinking; raising the budget fixed it</li></ul><p><strong>Why (the series&#39; shared lesson):</strong> chase infrastructure problems until you find how others solved them — don&#39;t settle for the first workaround that runs. Every misdiagnosis was recorded in the ADRs.</p></details><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The full ADRs (including the overturned misdiagnoses) live in the private repository; this page is the public digest.</p></div>',16)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
